int Font::textWidth(const char *text, int len)
{
    if (len == -1)
        len = strlen(text);
    int totalWidth = 0;
    for (int c = 0; c < len; ++c) {
        uint8_t ch = text[c];
        if (ch < firstChar) {
            totalWidth += spaceWidth;
            continue;
        }
        int width = xs[ch - firstChar + 1] - xs[ch - firstChar];
        totalWidth += width;
    }
    return totalWidth;
}

void Font::drawText(BaseDisplay &disp, const Palette16 &palette, Point pt, const char *text, int len)
{
    if (len == -1)
        len = strlen(text);
    int pitch = (xs[sizeof(xs) / sizeof(xs[0]) - 1] + 1) >> 1;
    for (int c = 0; c < len; ++c) {
        uint8_t ch = text[c];
        if (ch < firstChar) {
            disp.fill(Rect(pt.x, pt.y, pt.x + spaceWidth, pt.y + height), palette.bg());
            pt.x += spaceWidth;
            continue;
        }
        int pos = xs[ch - firstChar];
        int width = xs[ch - firstChar + 1] - pos;
        disp.copy4bit(pt, width, height, bits, pos, pitch, palette.cmap);
        pt.x += width;
    }
}

int main(int argc, char *argv[])
{
    if (SDL_Init(SDL_INIT_EVERYTHING) < 0)
    {
        printf("SDL Init failed\n");
        exit(1);
    }

    SDLDisplay display(480, 320, 2);

    bool quit = false;
    display.init();
    int t = 0;
    static const uint8_t face[8] = { 255, 195, 165, 129, 165, 153, 195, 255 };
    RGB565 face2[16 * 16];
    for (int i = 0; i < 16; ++i) {
        int t = 7 + (i < 8 ? i : 16 - i);
        auto fg = RGB565::rgb888(t * 16, 0, 0);
        for (int j = 0; j < 16; ++j) {
            face2[16 * i + j] = face[i >> 1] & (128 >> (j >> 1)) ? RGB565::rgb888(0xFFFFFF) : fg;
        }
    }
    //display.setClipRect(Rect(40, 40, 480 - 40, 320 - 40));
    display.setClipRect(Rect(5, 5, 480 - 5, 320 - 5));
    Font font;
    const char text[] = "Hello cruel world";
    int textw = font.textWidth(text);
    while(true) {
        Palette16 palette(RGB565::rgb888(0xFFFF00), RGB565::rgb888((t & 63) * 0x000400));
        Palette16 palette2(RGB565::rgb888(0x000000), RGB565::rgb888((t & 63) * 0x000400));
        t++;
        for (int i = 0; i < 30; ++i) {
            for (int j = 0; j < 20; ++j) {
                RGB565 colour = ((i ^ j) & 1) ? RGB565::rgb888(0xFFFFFF) : RGB565::rgb888(0x000000);
                display.fill(Rect(i * 16, j * 16, (i + 1) * 16, (j + 1) * 16), colour);
            }
        }
        for (int i = 0; i < 30; i += 4) {
            for (int j = 0; j < 20; j += 4) {
                display.copy(Rect(i * 16, j * 16, i * 16 + 16, j * 16 + 16), face2);
            }
        }
        for (int i = 2; i < 30; i += 4) {
            for (int j = 2; j < 20; j += 4) {
                display.copy1bit(Point(i * 16 + 4, j * 16 + 4), 8, 8, face, 0, 1, RGB565::rgb888(0x00FF00), RGB565::rgb888(0x000000));
            }
        }
        int cx = (t * 3) % (480 + 2 * 120) - 120;
        cx = 240;
        circle(display, cx, 160, 120, RGB565::rgb888(0xFFFF00));
        font.drawText(display, palette, Point(cx - textw / 2, 160 - font.height), text);
        font.drawText(display, palette2, Point(cx - textw / 2, 160), text);
        display.complete();

        usleep(20000);
        SDL_Event sdlEvent;
        bool quit = false;
        while(SDL_PollEvent(&sdlEvent)) {
            if (sdlEvent.type == SDL_QUIT)
                quit = true;
        }
        if (quit)
            break;
    }
    SDL_Quit();
    return 0;
}
